function findKthNumber(m, n, k) {
  let low = 1;
  let high = m * n;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    let count = 0;
    for (let row = 1; row <= m; row++) {
      count += Math.min(Math.floor(mid / row), n);
    }
    if (count >= k) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

