function findKthNumber(m, n, k) {
  // Walk the values upward, counting the cells equal to each one through its divisor pairs.
  let seen = 0;
  for (let value = 1; ; value++) {
    for (let d = 1; d * d <= value; d++) {
      if (value % d !== 0) continue;
      const e = value / d;
      if (d <= m && e <= n) seen++;
      if (d !== e && e <= m && d <= n) seen++;
    }
    if (seen >= k) return value;
  }
}

